/* Shared footer keeps the women-feature links beneath both columns. */
#why .why-laidies{padding-bottom:24px;row-gap:20px}
#why .why-laidies>.why-links{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:0}
#why .why-laidies>.why-links a{width:100%;height:100%;min-width:0;justify-content:center;text-align:center;padding:12px 20px}
@media(max-width:900px){#why .why-laidies>.why-links{grid-template-columns:1fr;gap:12px}}
#why .why-laidies>div:not(.why-links)>p:last-child{margin-bottom:0}
